import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

type AutomationsDisabledResponse = {
  automationsDisabled: boolean | null
}

export function useUpdateOrgAutomationsDisabledMutation(
  path: string,
): UseMutationResult<AutomationsDisabledResponse, Error, boolean | null> {
  return useMutation({
    mutationFn: async (disabled: boolean | null) => {
      const response = await verifiedFetchJSON(path, {
        method: 'PUT',
        body: {
          automations_disabled: disabled,
        },
      })
      const data = (await response.json()) as unknown

      if (!response.ok) {
        const message =
          data && typeof data === 'object' && 'error' in data && typeof (data as {error?: string}).error === 'string'
            ? (data as {error: string}).error
            : data &&
                typeof data === 'object' &&
                'message' in data &&
                typeof (data as {message?: string}).message === 'string'
              ? (data as {message: string}).message
              : `Failed to update automations setting: ${response.status} ${response.statusText}`
        throw new Error(message)
      }

      if (!data || typeof data !== 'object' || !('automationsDisabled' in data)) {
        throw new Error('Invalid response when updating automations setting')
      }

      const value = data.automationsDisabled
      if (typeof value !== 'boolean' && value !== null) {
        throw new Error('Invalid response when updating automations setting')
      }

      return {automationsDisabled: value}
    },
  })
}
