import {ControlGroup} from '@github-ui/control-group'
import {ActionMenu, ActionList, Heading, Label, Link, Stack} from '@primer/react'
import {useState} from 'react'
import type {OrgFirewallConfig} from '../types'
import {InlineMessage} from '@primer/react/experimental'
import {useUpdateOrgFirewallSettingsMutation} from '../hooks/use-org-firewall-mutation'

type FieldStatus = {status: 'error' | 'success'; message: string}
type PolicyValue = boolean | null

const DEFAULT_FIREWALL_CONFIG: OrgFirewallConfig = {
  enabled: null,
  useDefaultRules: null,
  allowCustomRules: null,
  rules: [],
}

function policyLabel(value: PolicyValue): string {
  if (value === null) return 'Let repositories decide'
  return value ? 'Enabled' : 'Disabled'
}

function PolicySelector({
  value,
  onChange,
  disabled,
  labelId,
  descriptionId,
  noPolicyDescription,
  enabledDescription,
  disabledDescription,
}: {
  value: PolicyValue
  onChange: (newValue: PolicyValue) => void
  disabled: boolean
  labelId: string
  descriptionId: string
  noPolicyDescription: string
  enabledDescription: string
  disabledDescription: string
}) {
  return (
    <ActionMenu>
      <ActionMenu.Button
        disabled={disabled}
        aria-labelledby={labelId}
        aria-describedby={descriptionId}
        variant="default"
      >
        {policyLabel(value)}
      </ActionMenu.Button>
      <ActionMenu.Overlay width="auto">
        <ActionList selectionVariant="single">
          <ActionList.Item selected={value === null} onSelect={() => onChange(null)}>
            Let repositories decide
            <ActionList.Description variant="block">{noPolicyDescription}</ActionList.Description>
          </ActionList.Item>
          <ActionList.Item selected={value === true} onSelect={() => onChange(true)}>
            Enabled
            <ActionList.Description variant="block">{enabledDescription}</ActionList.Description>
          </ActionList.Item>
          <ActionList.Item selected={value === false} onSelect={() => onChange(false)}>
            Disabled
            <ActionList.Description variant="block">{disabledDescription}</ActionList.Description>
          </ActionList.Item>
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}

function BinaryPolicySelector({
  value,
  onChange,
  disabled,
  labelId,
  descriptionId,
  enabledDescription,
  disabledDescription,
}: {
  value: PolicyValue
  onChange: (newValue: boolean) => void
  disabled: boolean
  labelId: string
  descriptionId: string
  enabledDescription: string
  disabledDescription: string
}) {
  const effectiveValue = value !== false
  return (
    <ActionMenu>
      <ActionMenu.Button
        disabled={disabled}
        aria-labelledby={labelId}
        aria-describedby={descriptionId}
        variant="default"
      >
        {effectiveValue ? 'Enabled' : 'Disabled'}
      </ActionMenu.Button>
      <ActionMenu.Overlay width="auto">
        <ActionList selectionVariant="single">
          <ActionList.Item selected={effectiveValue} onSelect={() => onChange(true)}>
            Enabled
            <ActionList.Description variant="block">{enabledDescription}</ActionList.Description>
          </ActionList.Item>
          <ActionList.Item selected={!effectiveValue} onSelect={() => onChange(false)}>
            Disabled
            <ActionList.Description variant="block">{disabledDescription}</ActionList.Description>
          </ActionList.Item>
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}

const FirewallHeader = () => {
  return (
    <div className="tmp-mt-4">
      <Heading as="h2" variant="small">
        Internet access
      </Heading>
      <p className="mt-1 mb-0">
        Configure firewall rules for {'Copilot cloud agent'} across all repositories in this organization.{' '}
        <Link
          href="https://docs.github.com/enterprise-cloud@latest/copilot/how-tos/agents/copilot-coding-agent/customizing-or-disabling-the-firewall-for-copilot-coding-agent"
          target="_blank"
          inline
        >
          Learn more about customizing network access
        </Link>
      </p>
    </div>
  )
}

export function OrgFirewallSettings({
  firewallEndpoint,
  allowlistUrl,
  initialValue = DEFAULT_FIREWALL_CONFIG,
}: {
  firewallEndpoint: string
  allowlistUrl: string
  initialValue?: OrgFirewallConfig
}) {
  const saveSettings = useUpdateOrgFirewallSettingsMutation(firewallEndpoint)
  const [config, setConfig] = useState<OrgFirewallConfig>(initialValue)
  const [isSaving, setIsSaving] = useState<boolean>(false)
  const [fieldStatus, setFieldStatus] = useState<FieldStatus | null>(null)

  const handlePolicySave = async (property: 'enabled' | 'useDefaultRules' | 'allowCustomRules', value: PolicyValue) => {
    setIsSaving(true)
    try {
      const newConfig = {...config, [property]: value}

      const result = await saveSettings.mutateAsync({
        enabled: newConfig.enabled,
        useDefaultRules: newConfig.useDefaultRules,
        allowCustomRules: newConfig.allowCustomRules,
      })
      if (result.requestFailed) {
        setFieldStatus({
          status: 'error',
          message: result.error || 'An error occurred saving firewall settings.',
        })
      } else {
        setFieldStatus(null)
        setConfig(result)
      }
    } catch {
      setFieldStatus({
        status: 'error',
        message: 'An error occurred saving firewall settings.',
      })
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <>
      <FirewallHeader />
      <Stack className="tmp-mt-3" gap="condensed">
        <ControlGroup>
          <ControlGroup.Item>
            <ControlGroup.Title id="org-firewall-enable-label" className="d-flex flex-items-center gap-1">
              Enable firewall <Label>Recommended</Label>
            </ControlGroup.Title>
            <ControlGroup.Description id="org-firewall-enable-description">
              Limit {'Copilot cloud agent'}&apos;s Internet access to only allow access to allowlisted locations.
              {config.enabled === false && (
                <InlineMessage variant="warning" size="small" className="mt-1">
                  Allowing full internet access may increase data exfiltration risks.
                </InlineMessage>
              )}
            </ControlGroup.Description>
            <ControlGroup.Custom>
              <PolicySelector
                value={config.enabled}
                onChange={v => handlePolicySave('enabled', v)}
                disabled={isSaving}
                labelId="org-firewall-enable-label"
                descriptionId="org-firewall-enable-description"
                noPolicyDescription="Let repository admins decide whether to enable the firewall"
                enabledDescription="Require the firewall to be enabled across all repositories"
                disabledDescription="Disable the firewall across all repositories"
              />
            </ControlGroup.Custom>
          </ControlGroup.Item>

          <ControlGroup.Item>
            <ControlGroup.Title id="org-use-default-rules-label">Recommended allowlist</ControlGroup.Title>
            <ControlGroup.Description id="org-use-default-rules-description">
              Allow access to locations frequently used to install tools, packages, and dependencies.{' '}
              <Link
                href="https://docs.github.com/en/copilot/reference/copilot-allowlist-reference#copilot-coding-agent-recommended-allowlist"
                target="_blank"
                inline
                aria-label="Learn more about the recommended allowlist"
              >
                Learn more
              </Link>
            </ControlGroup.Description>
            <ControlGroup.Custom>
              <PolicySelector
                value={config.useDefaultRules}
                onChange={v => handlePolicySave('useDefaultRules', v)}
                disabled={isSaving || config.enabled === false}
                labelId="org-use-default-rules-label"
                descriptionId="org-use-default-rules-description"
                noPolicyDescription="Let repository admins decide whether to use the recommended allowlist"
                enabledDescription="Enable the recommended allowlist across all repositories"
                disabledDescription="Disable the recommended allowlist across all repositories"
              />
            </ControlGroup.Custom>
          </ControlGroup.Item>

          <ControlGroup.Item>
            <ControlGroup.Title id="org-allow-custom-rules-label">Allow repository custom rules</ControlGroup.Title>
            <ControlGroup.Description id="org-allow-custom-rules-description">
              Allow repository administrators to add their own custom allowlist rules in addition to the organization
              allowlist.
            </ControlGroup.Description>
            <ControlGroup.Custom>
              <BinaryPolicySelector
                value={config.allowCustomRules}
                onChange={v => handlePolicySave('allowCustomRules', v)}
                disabled={isSaving || config.enabled === false}
                labelId="org-allow-custom-rules-label"
                descriptionId="org-allow-custom-rules-description"
                enabledDescription="Allow repository administrators to add custom allowlist rules in all repositories"
                disabledDescription="Prevent repository administrators from adding custom allowlist rules"
              />
            </ControlGroup.Custom>
          </ControlGroup.Item>

          <ControlGroup.LinkItem href={allowlistUrl}>
            <ControlGroup.Title id="org-allow-list-label">Organization custom allowlist</ControlGroup.Title>
            <ControlGroup.Description id="org-allow-list-description">
              Allow access to specific domains, IP addresses, or URLs for all repositories in this organization.
            </ControlGroup.Description>
          </ControlGroup.LinkItem>
        </ControlGroup>

        {fieldStatus && (
          <InlineMessage variant={fieldStatus.status === 'success' ? 'success' : 'critical'}>
            {fieldStatus.message}
          </InlineMessage>
        )}
      </Stack>
    </>
  )
}
