import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {OrgFirewallConfig, OrgFirewallUpdateRequest} from '../types'

export function useUpdateOrgFirewallSettingsMutation(
  path: string,
): UseMutationResult<OrgFirewallConfig, Error, OrgFirewallUpdateRequest> {
  return useMutation({
    mutationFn: async (request: OrgFirewallUpdateRequest) => {
      const response = await verifiedFetchJSON(path, {
        method: 'PUT',
        body: request,
      })
      const data = await response.json()
      if (!response.ok) {
        data.requestFailed = true
      }
      return data
    },
  })
}
