import React from 'react'
import {Heading} from '@primer/react'
import {clsx} from 'clsx'
import styles from './Ui.module.css'

export function PageHeading(props: {name: React.ReactNode; description?: React.ReactNode; meta?: React.ReactNode}) {
  return (
    <header className="Subhead">
      <Heading as="h2" className={clsx(styles.pageHeading, 'Subhead-heading')} id="github-copilot">
        {props.name} {props.meta}
      </Heading>
      {props.description ? <span className="Subhead-description">{props.description}</span> : null}
    </header>
  )
}

export function SectionHeading(props: {name: React.ReactNode; description?: React.ReactNode; meta?: React.ReactNode}) {
  return (
    <header className="Sectionhead">
      <Heading
        as="h3"
        className={clsx(styles.sectionHeading, 'Section-heading')}
        id={`${String(props.name).toLowerCase()}-section`}
      >
        {props.name} {props.meta}
      </Heading>
      {props.description ? <span className="Section-description">{props.description}</span> : null}
    </header>
  )
}

export function SubtleHeading(props: React.PropsWithChildren) {
  return <p className={styles.subtleHeading}>{props.children}</p>
}

function BoxSectionItem(props: React.PropsWithChildren) {
  return <li className={styles.boxSectionItem}>{props.children}</li>
}

export function BoxSection(props: React.PropsWithChildren) {
  return (
    <div className="Box">
      <ul className="Box-body">
        {simpleFlattenChildren(props.children).map((child, index) => (
          // eslint-disable-next-line @eslint-react/no-array-index-key
          <React.Fragment key={index}>
            {index > 0 ? <Divider /> : null}
            <BoxSectionItem>{child}</BoxSectionItem>
          </React.Fragment>
        ))}
      </ul>
    </div>
  )
}

// Slight modification from `ActionList.Divider` to increase the gap between items from space-2, to space-3
export function Divider() {
  return <li className={styles.divider} aria-hidden="true" />
}

export function CopilotCard({
  children,
  className,
  ...rest
}: React.PropsWithChildren<React.HTMLAttributes<HTMLDivElement>>) {
  return (
    <div className={clsx(styles.copilotCard, className)} {...rest}>
      {children}
    </div>
  )
}

export function AccessibleBreak() {
  return <br aria-hidden="true" />
}

export function Bold({
  children,
  as: Component = 'span',
  className,
  ...rest
}: React.PropsWithChildren<{as?: React.ElementType; className?: string} & React.HTMLAttributes<HTMLElement>>) {
  return (
    <Component className={clsx(styles.bold, className)} {...rest}>
      {children}
    </Component>
  )
}

export function Muted({children, className, ...rest}: React.PropsWithChildren<React.HTMLAttributes<HTMLSpanElement>>) {
  if (!children) {
    return null
  }

  return (
    <span className={clsx(styles.muted, className)} {...rest}>
      {children}
    </span>
  )
}

function AssignablesTableListItem(props: React.PropsWithChildren<{selected?: boolean; id: string | number}>) {
  const {children, selected, id} = props

  return (
    <li
      data-testid={`assignable-list-item-${id}`}
      className={clsx(styles.assignablesTableListItem, selected && styles.assignablesTableListItemSelected)}
    >
      {children}
    </li>
  )
}

type AssignablesTableProps = {
  content: React.ReactNode
  trailingActions?: React.ReactNode
  emptyState?: React.ReactNode
  className?: string
} & React.HTMLAttributes<HTMLDivElement>

function Table(props: AssignablesTableProps) {
  const {children, content, trailingActions, emptyState, className, ...rest} = props
  return (
    <div className={clsx(styles.table, className)} {...rest}>
      <div className={clsx('table-list-header', styles.tableHeader)}>
        <div className={styles.tableHeaderContent}>
          {content}
          {trailingActions}
        </div>
      </div>
      {emptyState ? <div className={styles.tableEmptyState}>{emptyState}</div> : null}
      <ul className={styles.tableList}>{children}</ul>
    </div>
  )
}

export const AssignablesTable = Object.assign(Table, {
  ListItem: AssignablesTableListItem,
})

// --

function simpleFlattenChildren(children: React.ReactNode) {
  const kids: React.ReactNode[] = []

  // eslint-disable-next-line github/array-foreach, @eslint-react/no-children-for-each
  React.Children.forEach(children, child => {
    if (React.isValidElement(child)) {
      if (child.type === React.Fragment) {
        const fragmentChild = child as React.ReactElement<React.ComponentProps<typeof React.Fragment>>
        kids.concat(simpleFlattenChildren(fragmentChild.props.children))
        return
      }
      kids.push(child)
    }
  })

  return kids
}
