import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {Banner} from '@primer/react'
import type {CopilotRunnerTypeOrgPayload} from '../types'
import {PageHeading} from '../traditional/components/Ui'
import {RunnerTypeSelection} from '../components/RunnerTypeSelection'
import {copilotForBusinessRunnerTypeRoute} from './runner-type-route'

export function RunnerTypeOrgSettingsEntrypointLegacy() {
  const payload = useRoutePayload<CopilotRunnerTypeOrgPayload>()
  return <RunnerTypeOrgSettingsPage payload={payload} />
}

export function RunnerTypeOrgSettingsEntrypoint() {
  const {data: payload} = useRouteQuery(copilotForBusinessRunnerTypeRoute, 'mainQuery')
  return <RunnerTypeOrgSettingsPage payload={payload} />
}

function RunnerTypeOrgSettingsPage({payload}: {payload: CopilotRunnerTypeOrgPayload}) {
  const agentName = 'Copilot cloud agent and Copilot code review'
  // The dotcom controller serializes runner_type via `.to_s`, which yields an
  // empty string when the org has no runner type set. Normalize to undefined so
  // RunnerTypeSelection's default ('standard') applies.
  const initialRunnerType = payload.runner_type || undefined
  return (
    <>
      <PageHeading name="Runner type" />
      <Banner className="tmp-mt-4 tmp-mb-4" variant="info" title="Supported agents" hideTitle>
        Runner type configuration applies to {agentName}.
      </Banner>
      <div className="tmp-mt-4 tmp-mb-4">
        <RunnerTypeSelection
          initialRunnerType={initialRunnerType}
          initialRunnerLabels={payload.runner_labels}
          initialRunnerGroupName={payload.runner_group_name}
          initialAllowRepoCustomRunner={payload.allow_repo_custom_runner}
          endpoint={payload.runner_settings_changed_callback_path}
          agentName={agentName}
        />
      </div>
    </>
  )
}
