import {KebabHorizontalIcon} from '@primer/octicons-react'
import {ActionMenu, ActionList, IconButton} from '@primer/react'
import {useRef} from 'react'
import styles from './RowActionsMenu.module.css'

type Props = React.PropsWithChildren<{
  isVisible: boolean
  testId?: string
}>

export function RowActionsMenu(props: Props) {
  const {isVisible, testId} = props

  const returnFocusRef = useRef(null)

  if (!isVisible) {
    return null
  }

  return (
    <ActionMenu>
      <ActionMenu.Anchor>
        <IconButton
          icon={KebabHorizontalIcon}
          variant="invisible"
          aria-label="Open seat options"
          ref={returnFocusRef}
          data-testid={testId}
          className={styles.menuButton}
        />
      </ActionMenu.Anchor>
      <ActionMenu.Overlay>
        <ActionList selectionVariant="single">{props.children}</ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}
